package main
import("net/http/httptest";"strings";"testing")
func TestIntegratedReceiverRoutes(t *testing.T){b:=&bridge{host:"127.0.0.1:19091",token:"sample-token"};for path,label:=range map[string]string{"/vseeface/receiver.html":"VSeeFace","/blender/receiver.html":"Blender","/unity/receiver.html":"Unity"}{r:=httptest.NewRequest("GET","http://"+b.host+path,nil);w:=httptest.NewRecorder();b.handler().ServeHTTP(w,r);s:=w.Body.String();if w.Code!=200||!strings.Contains(s,label)||strings.Contains(s,"__BRIDGE_KEY__")||!strings.Contains(s,"sample-token")||!strings.Contains(s,"https://anshaer.github.io/VMC/transmit/"){t.Fatalf("incorrect route: %s",path)}}}
func TestIntegratedRejectWrongHostAndOrigin(t *testing.T){b:=&bridge{host:"127.0.0.1:19091",token:"sample-token"};for _,host:=range []string{"attacker.example","127.0.0.1:19091"}{r:=httptest.NewRequest("GET","http://"+host+"/api/status",nil);r.Header.Set("X-Bridge-Key",b.token);r.Header.Set("Origin","https://attacker.example");w:=httptest.NewRecorder();b.handler().ServeHTTP(w,r);if w.Code!=403{t.Fatal("cross origin request accepted")}}}
